mapper.select:
SELECT so.id AS id, so.order_no AS orderNo, so.counter_no AS counterNo, so.cashier_name AS cashierName, m.name AS memberName, m.phone AS memberPhone, so.sale_time AS saleTime, so.item_count AS itemCount, so.goods_amount AS goodsAmount, so.discount_amount AS discountAmount, so.payable_amount AS payableAmount, so.paid_amount AS paidAmount, so.change_amount AS changeAmount, so.return_status AS returnStatus, COALESCE(r.refund_amount, 0) AS refundAmount FROM sales_order so LEFT JOIN member m ON m.id = so.member_id LEFT JOIN (SELECT sales_order_id, SUM(refund_amount) AS refund_amount FROM return_order GROUP BY sales_order_id) r ON r.sales_order_id = so.id
AND so.order_no LIKE CONCAT('%', #{q.orderNo}, '%')
AND so.cashier_name LIKE CONCAT('%', #{q.cashierName}, '%')
AND so.cashier_id = #{q.cashierId}
AND so.counter_no = #{q.counterNo}
AND (m.name LIKE CONCAT('%', #{q.memberKeyword}, '%') OR m.phone LIKE CONCAT('%', #{q.memberKeyword}, '%') OR m.member_no LIKE CONCAT('%', #{q.memberKeyword}, '%'))
AND EXISTS (SELECT 1 FROM payment_record pr WHERE pr.order_id = so.id AND pr.pay_type = #{q.payType})
AND so.sale_time >= #{beginTime}
AND so.sale_time < #{endTime}
AND so.payable_amount >= #{q.amountMin}
AND so.payable_amount <= #{q.amountMax}
AND so.return_status = #{q.returnStatus}
AND so.member_id IS NOT NULL
AND so.member_id IS NULL
ORDER BY so.sale_time DESC, so.id DESC
